halfNumber:
                dc.w $0000              ; Normal or extra time half number (1 or 2)
teamStarting:
                dc.w $0001              ; Number of team that starts the game or half
                                        ; gets random value 1 or 2; on halftime inverted (1 = 2, 2 = 1)
                                        ; gets new random value before start of first extra time
teamPlayingUp:
