debugMode:
                dc.w $0000
useAltBaseFlag:
                dc.w $0000
usePlaneOffsetFlag:
                dc.w 0,376,429,155,370,24,0,1
fireCounter:
                dc.w $0000              ; For any player input
menuControlsDirection2:
                dc.w $0000              ; These are perhaps the same flags as menuControlsDirection,
                                        ; but there is no blocking on key repeats
menuControlsDirection:
                dc.w $0000              ; 0 - Up
                                        ;  1 - up right
                                        ;  2 - right
                                        ;  3 - down right
                                        ;  4 - down
                                        ;  5 - down left
                                        ;  6 - left
                                        ;  7 - up left
                                        ; -1 - nothing
lastControls:
                dc.w $0000              ; CheckControls local controls in previous cycle
controlsHeldTimer:
                dc.w $0000              ; CheckControls local
                                        ; times how long controls are held
fire:
                dc.w $0000              ; -1 - Pressed
                                        ;  0 - not pressed
                                        ; these are combined input variables for the menus
shortFire:
                dc.w $0000
longFireTime:
                dc.w $0000
longFireFlag:
                dc.w $0000
up:
                dc.b $00
down:
                dc.b $00
left:
                dc.b $00
right:
                dc.b $00
fireResetFlag:
                dc.w $0000
; Menu *
currentMenuPtr:
                dc.l $00000000          ; Current menu, in packed form
menuStatus:
                dc.w $0000              ; 0 = Entering menu
                                        ; 1 = exiting
menuFade:
                dc.w $0000              ; Fade screen?
                                        ; 0 - no, 1 - yes (does it only
                                        ; once, when first showing the menu)
controlMask:
                dc.w $0000              ; Set by MenuProc:
                                        ; bit  9  8  7  6  5  4  3  2  1  0
                                        ;      |  |  |  |  |  |  |  |  |  +-- fire
                                        ;      |  |  |  |  |  |  |  |  +----- left
                                        ;      |  |  |  |  |  |  |  +-------- right
                                        ;      |  |  |  |  |  |  +----------- up
                                        ;      |  |  |  |  |  +-------------- down
                                        ;      |  |  |  |  +----------------- short fire
                                        ;      |  |  |  +-------------------- up left
                                        ;      |  |  +----------------------- down right
                                        ;      |  +-------------------------- up right
                                        ;      +----------------------------- down left
                                        ; It's been AND-ed by entries control mask.
menuTextBlinkCounter:
                dc.w $0000              ; When text is blinking (not frame)
deadInputTextVar:
                dc.w $0000
deadVar03:
                dc.w $0000
charTables:
                dc.l smallCharsTable
                dc.l bigCharsTable
numbersBuffer:
                dc.b $00,$00,$00,$00,$00,$00,$00,$00
shirtColorTable:
                dc.b $01,$02,$03,$06,$0A,$0B,$0C,$0D,$0E,$0F
hexLongStringBuffer:
                dc.b $00,$00,$00,$00,$00,$00,$00,$00,$00,$00 ; Buffer for converting a 32-bit value to an 8-digit hex ASCII string with null terminator.
hexWordStringBuffer:
                dc.b $00,$00,$00,$00,$00,$00 ; Buffer for converting a 16-bit panic code to a 4-digit hex ASCII string.
aStackOverflow:
                dc.b 'STACK OVERFLOW',0,0
                even
                xdef    _CallMenuCallback
_CallMenuCallback:
                movem.l d0-d7/a0-a6,-(sp)      ; save all regs (60 bytes)
                move.l  4+60(sp),a0             ; funcPtr (sp+64)
                jsr     (a0)
                movem.l (sp)+,d0-d7/a0-a6       ; restore original values
                rts
                xdef    _CallMenuOnSelect
_CallMenuOnSelect:
                movem.l d0-d7/a0-a6,-(sp)      ; save all regs with ORIGINAL values (60 bytes)
                move.l  4+60(sp),a0             ; funcPtr (sp+64)
                move.l  8+60(sp),a5             ; selectedEntry (sp+68)
                move.l  a5,-(sp)                ; push selectedEntry as C stack arg
                jsr     (a0)                    ; callback sees a5 = selectedEntry AND [sp+4] = entry
                addq.l  #4,sp                   ; clean up pushed arg
                movem.l (sp)+,d0-d7/a0-a6       ; restore ALL original values incl. a5
                rts
                xdef    _CallMenuFuncWithXY
_CallMenuFuncWithXY:
                movem.l d0-d7/a0-a6,-(sp)      ; save all regs with ORIGINAL values (60 bytes)
                move.l  4+60(sp),a0             ; funcPtr (sp+64)
                move.w  10+60(sp),d1            ; x low word (sp+70)
                move.w  14+60(sp),d2            ; y low word (sp+74)
                jsr     (a0)                    ; callback sees d1=x, d2=y
                movem.l (sp)+,d0-d7/a0-a6       ; restore ALL original values incl. d2
                rts
nextEntryDirectionOffsets:
                dc.w $0002,$0001,$0003,$0000

; char *[6]
defaultNamesTable:
                ; char *[6]
